use rspice_core::{Netlist, netlist::NetlistParseOptions, config::ExpressionDialect};

#[test]
fn remaining_routes() {
    for (name, source) in [
        ("retained_forward_chain", "Forward chain
.options temp={ambient}
.param ambient={later}
.param later=85
.end
"),
        ("provisional_domain", "Provisional domain
.param before={1/(TEMP-27)}
.param ambient=85
.options temp={ambient}
.end
"),
        ("incomplete_enclosing_scope", "Enclosing scope
.subckt local p n
.options temp={ambient}
.ends
.param ambient=85
.end
"),
        ("eager_analysis", "Eager analysis
.param stop={later}
.param later=1
V1 out 0 0
R1 out 0 1k
.dc V1 0 {stop} 0.1
.end
"),
        ("forward_source", "Forward source
.param value={later}
V1 out 0 DC {value}
R1 out 0 1k
.param later=1
.end
"),
    ] {
        for expression_dialect in [ExpressionDialect::Ngspice, ExpressionDialect::Xyce] {
            let result = Netlist::parse_with_options(source, NetlistParseOptions { expression_dialect, ..Default::default() });
            println!("{name} {expression_dialect:?}: {:?}", result.map(|n| (n.options.temp, n.params.get("ambient"))).map_err(|e| e.to_string()));
        }
    }
}
